Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Notation zlen l := (Z.of_nat (length l)).

Section CANSEC1. Context {rc : runConstT}.
Section Z4S34B.
  Variable AI : AMallocIface.
  Notation CI := (aci AI).
  Variables (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock) (rng_fs : alayout -> footprint -> Prop).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32) (m0 : amem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX2) (cbs : list byte) (pdt : aptr)
            (SBL SBH : Z) (rstk : region).
  Notation SP := (bv_unsigned sp).
  Notation SPF := (SP + -576).
  Notation n := (zlen src).
  Notation seg := ((dcap + 3) / 4).
  Notation DTL := (DTABLE_BYTES mtl).
  Hypothesis AH : AHEAP AI L RNG st LB m0.
  Hypothesis NFK : forall F k, ~ In (mkABlock (ABFake 0) F k) LB.
  Hypothesis ABL : forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b).
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl.
  Hypothesis HDT : In (HB pdt DT DTL) LB.
  Hypothesis TOK : x2_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells).
  Hypothesis LCB : zlen cbs = 4 * 2^tl.
  Hypothesis DSTF : (DST = 0 /\ dcap = 0) \/ (exists pb, In (HB pb DST dcap) LB).
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis NSM : n < 2^26.
  Hypothesis S16 : 16 <= SS.
  Hypothesis SRCB : 0 < n -> exists p, In (HB p SBL (SBH - SBL)) LB /\ SBL <= SS /\ SS + n <= SBH.
  Hypothesis DJ1 : DT + DTL <= SS \/ SS + n <= DT.
  Hypothesis DJ2 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis DJ3 : DT + DTL <= DST \/ DST + dcap <= DT.
  Hypothesis LOA : ATOP + 4096 <= lo.
  Hypothesis LOS : lo <= SP - HUF_DEC_STACK_A.
  Hypothesis SPT : SP + 16 < al_top L.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis TPA : tp = Z_to_bv 64 ATP.
  Hypothesis HINV : harness_invA m0.
  Hypothesis RCL : rclean m0 rstk.
  Hypothesis RLO : r_lo rstk <= lo.
  Hypothesis RHI : SP <= r_hi rstk.
  Hypothesis RRL : ATOP <= r_rlo rstk.
  Hypothesis RRS : rrng RNG rstk.
  Hypothesis WSK : rng RNG lo (al_top L - lo).
  Hypothesis WIM : rng_aimg RNG.
  Hypothesis WIS : rng_aimg_sh RNG.
  Hypothesis WFS : rng_fs L RNG.

  Notation DW := [(lo, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_postA AI L RNG ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB DST dcap lo m0).
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  Notation ZB l := (l AI L RNG st LB rng_fs ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc m0 DST dcap SS DT mtl tl lo src
                      cells cbs pdt SBL SBH rstk AH NFK ABL MTL TLM HDT TOK ECB LCB DSTF DC BYS NSM S16 SRCB DJ1 DJ2 DJ3
                      LOA LOS SPT SP16 TPA HINV RCL RLO RHI RRL RRS WSK WIM WIS WFS) (only parsing).
  Notation Z4SF' mm spl bd4 := (Z4SF ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT mtl tl lo src cbs mm spl bd4)
    (only parsing).

  (* [comment removed for export] *)
  Variables (O Lk Qe : Z).
  Hypothesis D6 : 6 <= dcap.
  Hypothesis O6 : 6 <= O.
  Hypothesis LK1 : 1 <= Lk.
  Hypothesis OLN : O + Lk <= n.
  Hypothesis QE : 0 <= Qe <= dcap.
  Variables (w40 w168 w176 w184 w192 w200 w208 w216 w224 w232 w240 w248 w256 w264 w272 w280 w288 w296 w304 : word)
            (j0 j1 jp : list byte).

  (* [comment removed for export] *)
  Notation ZS pc mm r1 r5 r6 r7 r8 r9 r10 r11 r12 r13 r14 r15 r16 r17 r18 r19 r20 r21 r22 r23 r24 r25 r26 r27 r28 r29
             r30 r31 :=
    (MS (mkR r1 (Z_to_bv 64 (SP + -576)) gp tp r5 r6 r7 r8 r9 r10 r11 r12 r13 r14 r15 r16 r17 r18 r19 r20 r21 r22 r23
             r24 r25 r26 r27 r28 r29 r30 r31) FR (Z_to_bv 64 pc) fc None mm (seg_rom asegs)) (only parsing).
  (* [comment removed for export] *)
  Notation Z4 pc mm r1 r5 r6 r7 r8 r9 r10 r11 r12 r13 r14 r15 r16 r17 r18 r19 r20 r21 r23 r26 r28 r29 r30 r31 :=
    (ZS pc mm r1 r5 r6 r7 r8 r9 r10 r11 r12 r13 r14 r15 r16 r17 r18 r19 r20 r21 (Z_to_bv 64 (DST + Qe - 7)) r23
        (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + Qe)) r26 (Z_to_bv 64 2147450880) r28 r29 r30 r31) (only parsing).

  Notation SPA4 := (SPA w40 w168 w176 w184 w192 w200 w208 w216 w224 w232 w240 w248 w256 w264 w272 w280 w288 w296 w304
                        (Z_to_bv 64 (DT + 4)) j0 j1) (only parsing).
  (* [comment removed for export] *)
  Notation Z34M mm c b p := (Z4SF' mm SPA4 (BD4A c b jp p (Z_to_bv 64 (SS + O)) (Z_to_bv 64 (SS + O + 8)))) (only parsing).

  (* [comment removed for export] *)
  Hypothesis K34 : forall mm' (spl : list cell) (cx bx px sx lx : word) (jx : list byte)
                     (z1 z5 z6 z7 z8 z9 z10 z11 z12 z13 z14 z15 z16 z17 z18 z19 z20 z21 z22 z23 z24 z25 z26 z27 z28 z29 z30 z31 : word),
    Z4SF' mm' spl (BD4A cx bx jx px sx lx) -> cells_size spl = 320%nat ->
    evtF asegs RNG POST (ZS 0x8d554 mm' z1 z5 z6 z7 z8 z9 z10 z11 z12 z13 z14 z15 z16 z17 z18 z19 z20 z21 z22 z23 z24 z25 z26
                            z27 z28 z29 z30 z31).

  Notation ZB3 l := (ZB l O Lk Qe D6 O6 LK1 OLN QE w40 w168 w176 w184 w192 w200 w208 w216 w224 w232 w240 w248 w256 w264 w272
                        w280 w288 w296 w304 j0 j1 jp K34) (only parsing).

  Lemma z34b_ff : 0x10007fff8000 <= SPF /\ SP <= 2^47 /\ ATOP + 4096 <= lo /\ lo + 8192 <= SP.
Proof using All.
ltac2:(KReplay.run1 (kr_t_AF_huf_z4s34b ()) ["CANSEC1"; "Z4S34B"] "p;yp-1p10000p4p710R0p8p1000Gp4p70P0p8p1001>p4p7210p1001jp4p710p8g002Hly0Tp,2rcp,2AIp,1Lp,3RNGp,2stp,2LBp,6rng_fsp,2rap,2spp,2gpp,2tpp,2s0p,2s1p,2s2p,2s3p,2s4p,2s5p,2s6p,2s7p,2s8p,2s9p,3s10p,3s11p,2FRp,2fcp,2m0p,3DSTp,4dcapp,2SSp,2DTp,3mtlp,2tlp,2lop,3srcp,5cellsp,3cbsp,3pdtp,3SBLp,3SBHp,4rstkp,2AHp,3NFKp,3ABLp,3MTLp,3TLMp,3HDTp,3TOKp,3ECBp,3LCBp,4DSTFp,2DCp,3BYSp,3NSMp,3S16p,4SRCBp,3DJ1p,3DJ2p,3DJ3p,3LOAp,3LOSp,3SPTp,4SP16p,3TPAp,4HINVp,3RCLp,3RLOp,3RHIp,3RRLp,3RRSp,3WSKp,3WIMp,3WISp,3WFSMy0o"). Qed.

  Ltac lnd K := (try change 18446744073709551615 with (Z.ones 64) in K); rewrite ?Z.land_ones in K by lia;
                rewrite ?Z.mod_small in K by lia.
  Ltac z34_pre :=
    pose proof z34b_ff as FF;
    let RSP := fresh "RSP" in pose proof (bv_unsigned_in_range 64 sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
    let ABD := fresh "ABD" in let DAT := fresh "DAT" in
    pose proof (ZB z4s1_dblk D6) as (_ & _ & ABD & DAT & _ & _); unfold ablk, KLS, AIMG_HI in ABD;
    let AT := fresh "AT" in pose proof ATOP_range as AT; unfold ATOP_MIN, ATOP_MAX in AT;
    let TLR := fresh "TLR" in pose proof TOK as (TLR & _); unfold HUF_TABLELOG_MAX in TLR;
    let BL1 := fresh "BL1" in let BL2 := fresh "BL2" in let BL3 := fresh "BL3" in let BL4 := fresh "BL4" in
    let BL5 := fresh "BL5" in let BL6 := fresh "BL6" in
    pose proof (ZB z4s_blocks) as (BL1 & BL2 & BL3 & BL4 & BL5 & BL6); unfold AIMG_HI in *;
    destruct BL5 as [BL5|BL5]; [lia|]; destruct BL6 as [BL6|BL6]; [lia|].
  Ltac z34_pack H c b p :=
    lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mc _) => assert (H : Z34M mc c b p) by z4sf_pack end.
  Ltac z34_epack H :=
    lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mc _) => eassert (H : Z34M mc _ _ _) by z4sf_pack end.
  (* [comment removed for export] *)
  Ltac zify_lts K :=
    unfold bv_lts in K; rewrite ?land7_mod in K;
    rewrite !signed_lit_small64 in K by (Z.div_mod_to_equations; lia);
    zify_bool K.

  (* [comment removed for export] *)
  Lemma z34_le : forall p pt B mm (c : word)
      (x1 x5 x6 x7 x8 x9 x11 x12 x14 x15 x16 x17 x18 x19 x20 x21 x23 x26 x28 x29 x30 x31 : word),
    Z34M mm c (Z_to_bv 64 B) (Z_to_bv 64 (SS + O + pt)) -> DST <= p <= DST + Qe -> 0 <= pt -> pt + 8 <= Lk -> 0 <= B <= 64 ->
    evtF asegs RNG POST (Z4 0x8d108 mm x1 x5 x6 x7 x8 x9 (Z_to_bv 64 p) x11 x12 (Z_to_bv 64 (SS + O + pt)) x14 x15 x16 x17 x18
